import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Home, Dumbbell, Trophy, Map, User, LogOut, Zap } from 'lucide-react';

const navItems = [
  { path: '/dashboard', label: 'Home', icon: Home },
  { path: '/workouts', label: 'Workouts', icon: Dumbbell },
  { path: '/quests', label: 'Quests', icon: Map },
  { path: '/leaderboard', label: 'Ranks', icon: Trophy },
  { path: '/profile', label: 'Profile', icon: User },
];

export default function Navbar() {
  const { user, logout } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();

  const handleLogout = () => { logout(); navigate('/login'); };

  return (
    <>
      {/* Top bar */}
      <div style={{
        position: 'fixed', top: 0, left: 0, right: 0, zIndex: 100,
        background: 'rgba(10,11,15,0.95)', backdropFilter: 'blur(20px)',
        borderBottom: '1px solid rgba(0,245,160,0.1)',
        padding: '12px 24px',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{
            width: 36, height: 36, borderRadius: 10,
            background: 'linear-gradient(135deg, #00f5a0, #00c6ff)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 18, fontWeight: 900,
          }}>⚡</div>
          <span style={{ fontFamily: 'Rajdhani', fontWeight: 700, fontSize: 22, color: '#00f5a0', letterSpacing: 1 }}>
            FitLvl
          </span>
        </div>

        {user && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <Zap size={14} color="#f4c430" fill="#f4c430" />
              <span style={{ color: '#f4c430', fontWeight: 700, fontSize: 14, fontFamily: 'Rajdhani' }}>
                {user.xp_percentage}%
              </span>
              <div style={{
                width: 80, height: 6, background: 'var(--bg-elevated)',
                borderRadius: 3, overflow: 'hidden',
              }}>
                <div style={{
                  width: `${user.xp_percentage}%`, height: '100%',
                  background: 'linear-gradient(90deg, #f4c430, #ff8c00)',
                  borderRadius: 3, transition: 'width 0.5s',
                }} />
              </div>
              <span style={{ color: 'var(--text-secondary)', fontSize: 12, fontFamily: 'Rajdhani' }}>
                LVL {user.level}
              </span>
            </div>

            <div style={{
              width: 36, height: 36, borderRadius: '50%',
              background: 'var(--bg-elevated)',
              border: '2px solid var(--accent)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 18,
            }}>
              {user.avatar}
            </div>

            <button onClick={handleLogout} className="btn btn-ghost" style={{ padding: '6px 10px' }}>
              <LogOut size={16} />
            </button>
          </div>
        )}
      </div>

      {/* Bottom nav for mobile / sidebar for desktop */}
      <nav style={{
        position: 'fixed', bottom: 0, left: 0, right: 0, zIndex: 100,
        background: 'rgba(10,11,15,0.97)', backdropFilter: 'blur(20px)',
        borderTop: '1px solid rgba(0,245,160,0.1)',
        display: 'flex', justifyContent: 'space-around',
        padding: '8px 0 env(safe-area-inset-bottom)',
      }}>
        {navItems.map(({ path, label, icon: Icon }) => {
          const active = location.pathname === path;
          return (
            <Link key={path} to={path} style={{
              display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4,
              padding: '6px 16px', borderRadius: 10, textDecoration: 'none',
              color: active ? 'var(--accent)' : 'var(--text-muted)',
              background: active ? 'var(--accent-dim)' : 'transparent',
              transition: 'all 0.2s',
              minWidth: 60,
            }}>
              <Icon size={20} />
              <span style={{ fontSize: 10, fontFamily: 'Rajdhani', fontWeight: 600, letterSpacing: 0.5 }}>
                {label}
              </span>
            </Link>
          );
        })}
      </nav>
    </>
  );
}
